documents.auth/passwords.py:
def verify_password(password, password_hash):
    """Verify a salted bcrypt password hash; reject invalid credentials."""
    return bcrypt.checkpw(password, password_hash)

documents.auth/tokens.py:
def decode_access_token(token, signing_key):
    """Validate JWT signature and expiration before accepting the subject."""
    return jwt.decode(token, signing_key, algorithms=["HS256"])

documents.auth/principal.py:
def require_active_user(user):
    """Reject inactive or deleted users with an authentication error."""
    if user is None or not user.is_active:
        raise AuthenticationError()

documents.security/ownership.py:
def require_repository_owner(profile, user_id):
    """Prevent cross-user repository access. Ownership comes from the authenticated principal."""
    if profile.user_id != user_id:
        raise NotFound()

documents.database/pool.py:
def database_pool(url):
    """Bound database connections with pool_size=5 and max_overflow=0."""
    return create_async_engine(url, pool_size=5, max_overflow=0)

documents.settings/secrets.py:
def validate_signing_secret(environment, signing_key):
    """Production requires an explicit random secret of at least 32 bytes; reject placeholders."""
    if environment == "production" and len(signing_key.encode()) < 32:
        raise ConfigurationError()

documents.github/revision.py:
async def resolve_revision(client, owner, repository):
    """Resolve the default branch to an immutable forty-character commit SHA."""
    return await client.resolve_commit(owner, repository)

documents.github/paths.py:
def safe_path(path):
    """Reject absolute paths, traversal, symlinks and binary files before ingestion."""
    return not path.startswith("/") and ".." not in path.split("/")

documents.jobs/retry.py:
def retry_delay(attempt):
    """Retry transient failures with bounded exponential backoff; stop after exhaustion."""
    return min(60, 2 ** attempt)

documents.jobs/leases.py:
def claim_job(job, worker_id):
    """Claim queued work with a lease and fencing token; a stale worker cannot publish."""
    return job.new_attempt(worker_id)

documents.jobs/cancellation.py:
def check_cancellation(job):
    """Cooperative cancellation stops publication without hard process termination."""
    if job.cancel_requested_at:
        raise JobCancelled()

documents.search/fusion.py:
def reciprocal_rank_fusion(keyword_rank, semantic_rank):
    """Combine one-based ranks with equal weights and k=60, never mix raw scores."""
    return 1 / (60 + keyword_rank) + 1 / (60 + semantic_rank)

documents.search/citations.py:
def verify_citation(source, chunk):
    """Canonical path, commit SHA, inclusive line range and exact excerpt must match persisted text."""
    assert chunk.text == "\n".join(source.text.splitlines()[chunk.line_start - 1:chunk.line_end])

documents.http/errors.py:
def public_error(exception):
    """Sanitize failure responses: hide credentials, SQL parameters and private query contents."""
    return {"detail": "Service temporarily unavailable"}

documents.cache/response.py:
def cached_response(cache, key):
    """Read an HTTP response from a cache with a short expiration time."""
    return cache.get(key)
